"use strict";(self.webpackChunk_=self.webpackChunk_||[]).push([["7962"],{46(e,n,s){s.r(n),s.d(n,{metadata:()=>t,default:()=>c,frontMatter:()=>a,contentTitle:()=>o,toc:()=>d,assets:()=>l});var t=JSON.parse('{"id":"foundations/history-timeline","title":"History \u2014 Timeline","description":"Key AI milestones from 1950 to the present, dense and scannable.","source":"@site/docs/foundations/history-timeline.md","sourceDirName":"foundations","slug":"/foundations/history-timeline","permalink":"/aible/docs/foundations/history-timeline","draft":false,"unlisted":false,"tags":[],"version":"current","sidebarPosition":3,"frontMatter":{"sidebar_position":3,"title":"History \u2014 Timeline","description":"Key AI milestones from 1950 to the present, dense and scannable."},"sidebar":"mainSidebar","previous":{"title":"What is AI?","permalink":"/aible/docs/foundations/what-is-ai"},"next":{"title":"History \u2014 Narrative","permalink":"/aible/docs/foundations/history-narrative"}}'),r=s(4848),i=s(8453);let a={sidebar_position:3,title:"History \u2014 Timeline",description:"Key AI milestones from 1950 to the present, dense and scannable."},o="History \u2014 Timeline",l={},d=[{value:"1950s\u20131960s: The founding era",id:"1950s1960s-the-founding-era",level:2},{value:"1970s\u20131980s: Expert systems and first winter",id:"1970s1980s-expert-systems-and-first-winter",level:2},{value:"Late 1980s\u20131990s: Connectionism and statistical learning",id:"late-1980s1990s-connectionism-and-statistical-learning",level:2},{value:"2000s: The shallow ML era",id:"2000s-the-shallow-ml-era",level:2},{value:"2010s: The deep learning revolution",id:"2010s-the-deep-learning-revolution",level:2},{value:"2020s: The LLM era",id:"2020s-the-llm-era",level:2}];function h(e){let n={a:"a",em:"em",h1:"h1",h2:"h2",header:"header",hr:"hr",p:"p",strong:"strong",...(0,i.R)(),...e.components};return(0,r.jsxs)(r.Fragment,{children:[(0,r.jsx)(n.header,{children:(0,r.jsx)(n.h1,{id:"history--timeline",children:"History \u2014 Timeline"})}),"\n",(0,r.jsxs)(n.p,{children:["A reference timeline: what happened, when, and why it mattered. For the story connecting these events, see ",(0,r.jsx)(n.a,{href:"/aible/docs/foundations/history-narrative",children:"History \u2014 Narrative"}),"."]}),"\n",(0,r.jsx)(n.hr,{}),"\n",(0,r.jsx)(n.h2,{id:"1950s1960s-the-founding-era",children:"1950s\u20131960s: The founding era"}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.strong,{children:"1950"}),' \u2014 Alan Turing, "Computing Machinery and Intelligence" \u2014 Poses the question "Can machines think?" and proposes the Imitation Game as a practical test. Establishes the conceptual frame that AI research would argue with for the next seventy years.']}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.strong,{children:"1956"}),' \u2014 Dartmouth Conference \u2014 John McCarthy, Marvin Minsky, Claude Shannon, and Nathaniel Rochester organize the summer workshop that coins the term "Artificial Intelligence." The field is born as a named discipline.']}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.strong,{children:"1957"})," \u2014 Perceptron \u2014 Frank Rosenblatt builds the Mark I Perceptron at Cornell, a physical machine learning to recognize patterns from punch cards. The first practical implementation of a learned classifier."]}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.strong,{children:"1958"})," \u2014 LISP \u2014 John McCarthy develops LISP at MIT, the programming language that would dominate AI research for the next thirty years. Symbolic computation as the substrate for intelligence."]}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.strong,{children:"1965"})," \u2014 DENDRAL \u2014 Edward Feigenbaum and Joshua Lederberg at Stanford build the first expert system: DENDRAL infers molecular structure from mass spectrometer data. Demonstrates that encoded domain knowledge can perform at expert level."]}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.strong,{children:"1966"})," \u2014 ELIZA \u2014 Joseph Weizenbaum at MIT creates ELIZA, a chatbot that mirrors user statements to simulate a psychotherapist. Users report feeling genuinely understood. Weizenbaum is disturbed by this; his 1976 book ",(0,r.jsx)(n.em,{children:"Computer Power and Human Reason"})," is the earliest serious critique of anthropomorphizing AI."]}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.strong,{children:"1969"})," \u2014 Minsky & Papert, ",(0,r.jsx)(n.em,{children:"Perceptrons"})," \u2014 Prove that single-layer perceptrons cannot learn XOR or any non-linearly separable function. Widely (and somewhat unfairly) interpreted as refuting neural networks entirely. Contributes to the first AI winter."]}),"\n",(0,r.jsx)(n.hr,{}),"\n",(0,r.jsx)(n.h2,{id:"1970s1980s-expert-systems-and-first-winter",children:"1970s\u20131980s: Expert systems and first winter"}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.strong,{children:"1972"})," \u2014 PROLOG \u2014 Alain Colmerauer develops PROLOG, a logic programming language. With LISP, forms the two dominant AI languages of the era."]}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.strong,{children:"1974\u20131980"})," \u2014 First AI Winter \u2014 Funding cuts in the US and UK following failed promises. The Lighthill Report (1973) in the UK concludes that AI has failed to achieve its goals. DARPA ends its speech understanding program. Research continues but at reduced scale."]}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.strong,{children:"1980"})," \u2014 XCON (R1) \u2014 Digital Equipment Corporation deploys XCON, an expert system that configures VAX computer orders. Reportedly saves DEC millions of dollars per year in configuration errors (the often-cited $40M annual figure is poorly sourced and likely cumulative). Triggers massive corporate investment in expert systems through the mid-1980s."]}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.strong,{children:"1981"})," \u2014 Japan's Fifth Generation Computer Project \u2014 Japan announces a ten-year, $850M program to build AI-capable hardware and software. Triggers matching investment in the US and Europe. Much of the promised capability is not delivered."]}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.strong,{children:"1986"}),' \u2014 Backpropagation popularized \u2014 Rumelhart, Hinton & Williams publish "Learning representations by back-propagating errors" in ',(0,r.jsx)(n.em,{children:"Nature"}),". Backpropagation was independently discovered earlier (Werbos, 1974; LeCun, 1985) but this paper's clarity and framing re-ignites interest in neural networks."]}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.strong,{children:"1987\u20131993"})," \u2014 Second AI Winter \u2014 The expert systems market collapses as maintenance costs balloon and limitations become clear. LISP machine companies fail. The AI industry loses most of its commercial funding for several years."]}),"\n",(0,r.jsx)(n.hr,{}),"\n",(0,r.jsx)(n.h2,{id:"late-1980s1990s-connectionism-and-statistical-learning",children:"Late 1980s\u20131990s: Connectionism and statistical learning"}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.strong,{children:"1989"})," \u2014 Convolutional networks \u2014 Yann LeCun at Bell Labs applies convolutional neural networks to handwritten digit recognition. LeNet achieves state-of-the-art on the USPS zip code dataset. The ideas are correct; the hardware is not yet adequate."]}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.strong,{children:"1997"}),' \u2014 LSTM published \u2014 Hochreiter & Schmidhuber, "Long Short-Term Memory" (',(0,r.jsx)(n.em,{children:"Neural Computation"}),"). The core ideas were developed in Hochreiter's 1991 diploma thesis but went unnoticed for years; the 1997 paper is when the field adopted LSTMs. Solves the vanishing gradient problem for recurrent networks, enabling sequence modeling over long time horizons."]}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.strong,{children:"1995"})," \u2014 Support Vector Machines \u2014 Corinna Cortes and Vladimir Vapnik publish the SVM paper. SVMs and kernel methods dominate machine learning benchmarks through the 2000s, outperforming neural networks on most tasks with less compute. The theoretical foundations (VC dimension, structural risk minimization) give the field a rigorous grounding."]}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.strong,{children:"1997"}),' \u2014 Deep Blue beats Kasparov \u2014 IBM\'s Deep Blue defeats world chess champion Garry Kasparov 3.5\u20132.5 in a six-game match. The win is based on search and evaluation functions, not learning. The AI community is ambivalent: chess was supposed to prove intelligence; Deep Blue proves it is "just search."']}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.strong,{children:"1998"})," \u2014 LeNet-5 \u2014 Yann LeCun publishes the definitive convolutional network paper and the MNIST benchmark. The MNIST dataset becomes the standard benchmark for handwritten digit recognition for the next two decades."]}),"\n",(0,r.jsx)(n.hr,{}),"\n",(0,r.jsx)(n.h2,{id:"2000s-the-shallow-ml-era",children:"2000s: The shallow ML era"}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.strong,{children:"2001"})," \u2014 Random Forests \u2014 Leo Breiman publishes random forests. Ensemble methods \u2014 combining many weak learners \u2014 become the dominant approach for tabular classification tasks."]}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.strong,{children:"2001"})," \u2014 Wikipedia launches \u2014 Within a decade, Wikipedia provides a massive corpus of structured human knowledge in machine-readable form. Its influence on language model pretraining is enormous."]}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.strong,{children:"2006"})," \u2014 Hinton's deep belief networks \u2014 Geoffrey Hinton, Simon Osindero, and Yee-Whye Teh show that deep networks can be pre-trained layer-by-layer using restricted Boltzmann machines. Reignites interest in deep learning after a decade of SVM dominance."]}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.strong,{children:"2009"})," \u2014 ImageNet \u2014 Fei-Fei Li and colleagues at Stanford release ImageNet: 14 million labeled images across 20,000 categories. The dataset that would make the deep learning revolution possible."]}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.strong,{children:"2009"})," \u2014 XGBoost precursors \u2014 Gradient boosted trees (Friedman, 2001) are refined throughout the decade. XGBoost is published by Chen & Guestrin in 2016, but the gradient boosting family dominates tabular ML competitions through this period."]}),"\n",(0,r.jsx)(n.hr,{}),"\n",(0,r.jsx)(n.h2,{id:"2010s-the-deep-learning-revolution",children:"2010s: The deep learning revolution"}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.strong,{children:"2012"})," \u2014 AlexNet \u2014 Alex Krizhevsky, Ilya Sutskever, and Geoffrey Hinton win the ImageNet Large Scale Visual Recognition Challenge with a 15.3% top-5 error rate, compared to the second place's 26.2%. The gap is large enough that the field reroutes. GPUs, large datasets, and deep convolutional networks become the dominant paradigm overnight."]}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.strong,{children:"2013"}),' \u2014 word2vec \u2014 Tomas Mikolov and colleagues at Google publish word2vec: dense vector embeddings of words trained on co-occurrence statistics. For the first time, words have geometric relationships \u2014 "king \u2212 man + woman \u2248 queen." Transfer learning begins for NLP.']}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.strong,{children:"2014"})," \u2014 GANs \u2014 Ian Goodfellow and colleagues introduce Generative Adversarial Networks. A generator network and a discriminator network compete; the generator learns to produce realistic samples. Launches a decade of generative modeling research."]}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.strong,{children:"2014"})," \u2014 Attention (seq2seq) \u2014 Bahdanau, Cho & Bengio publish the first attention mechanism for neural machine translation. Allows decoder to look back at the full encoder sequence rather than squeezing it through a single hidden state vector."]}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.strong,{children:"2015"})," \u2014 ResNets \u2014 He, Zhang, Ren & Sun at Microsoft Research publish Deep Residual Networks, enabling training of 152-layer networks via residual connections. Win the 2015 ImageNet competition by a large margin. Residual connections become standard across virtually every deep architecture."]}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.strong,{children:"2016"})," \u2014 AlphaGo \u2014 DeepMind's AlphaGo defeats world Go champion Lee Sedol 4\u20131. Unlike Deep Blue, AlphaGo learns from human games and self-play using deep reinforcement learning. Go was supposed to be too complex for brute-force search; AlphaGo renders the argument moot."]}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.strong,{children:"2017"}),' \u2014 "Attention Is All You Need" \u2014 Vaswani et al. at Google publish the Transformer architecture: attention mechanisms replace recurrence entirely. Faster to train, parallelizable, and eventually more capable. The most consequential ML paper of the decade.']}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.strong,{children:"2018"})," \u2014 BERT \u2014 Google's BERT (Bidirectional Encoder Representations from Transformers) achieves state-of-the-art on eleven NLP tasks simultaneously through unsupervised pretraining on Wikipedia + BooksCorpus, followed by task-specific fine-tuning. Transfer learning for NLP becomes the dominant paradigm."]}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.strong,{children:"2018"})," \u2014 GPT-1 \u2014 OpenAI releases GPT (Generative Pre-trained Transformer). Unlike BERT's bidirectional encoding, GPT uses a causal decoder that predicts the next token. The architecture that eventually becomes GPT-4 and its successors."]}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.strong,{children:"2019"})," \u2014 GPT-2 \u2014 OpenAI trains a 1.5B parameter autoregressive language model. The generated text is coherent enough that OpenAI initially withholds the full model, citing misuse risk. This decision is widely debated; the model is eventually released."]}),"\n",(0,r.jsx)(n.hr,{}),"\n",(0,r.jsx)(n.h2,{id:"2020s-the-llm-era",children:"2020s: The LLM era"}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.strong,{children:"2020"})," \u2014 GPT-3 \u2014 OpenAI releases GPT-3 (175B parameters). Few-shot prompting \u2014 providing a few examples in the context window rather than fine-tuning \u2014 proves surprisingly effective. The API business model for LLMs begins."]}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.strong,{children:"2021"})," \u2014 GitHub Copilot (preview) \u2014 OpenAI Codex, fine-tuned on code, powers GitHub Copilot. The first mainstream AI coding assistant. By 2023, Copilot has millions of active users."]}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.strong,{children:"2021"})," \u2014 DALL-E \u2014 OpenAI's DALL-E generates images from text descriptions using a transformer over image patches and text tokens. Multimodal generation becomes accessible."]}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.strong,{children:"2022"})," \u2014 Stable Diffusion \u2014 Stability AI releases Stable Diffusion: a high-quality text-to-image diffusion model with open weights. Launches an ecosystem of image generation tools. Latent diffusion (operating in a compressed latent space rather than pixel space) makes generation viable on consumer hardware."]}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.strong,{children:"2022"})," \u2014 InstructGPT / RLHF \u2014 OpenAI publishes InstructGPT: a method for aligning language models with human preferences using Reinforcement Learning from Human Feedback (RLHF). Models become dramatically more useful and less likely to produce harmful outputs. The technique becomes standard for all major assistant models."]}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.strong,{children:"2022"})," \u2014 ChatGPT \u2014 OpenAI releases ChatGPT based on GPT-3.5 with RLHF fine-tuning. Reaches 100 million users in two months \u2014 the fastest consumer product adoption ever recorded at that point. Mainstreams large language models for non-technical users."]}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.strong,{children:"2023"})," \u2014 GPT-4 \u2014 OpenAI's GPT-4 is released. Multimodal (text + images), significantly stronger reasoning, passes the Bar exam (early reports claimed top 10%; subsequent analysis places performance closer to median law school graduate). First model where capability differences from its predecessor are widely noted by professional users."]}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.strong,{children:"2023"})," \u2014 Llama \u2014 Meta releases Llama and Llama 2 with open weights. Enables a wave of fine-tuned variants (Alpaca, Vicuna, Mistral) and on-premise deployment. Shifts the industry conversation toward open vs. closed model strategies."]}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.strong,{children:"2023"})," \u2014 Claude \u2014 Anthropic releases Claude, trained with Constitutional AI (CAI): a self-critique and revision process that reduces the need for human labeling in alignment. Demonstrates that safety-oriented training can produce highly capable models."]}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.strong,{children:"2023"})," \u2014 GPT-4V, Gemini \u2014 Multimodal becomes standard. GPT-4V adds vision; Google's Gemini is natively multimodal across text, images, audio, and video from the start."]}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.strong,{children:"2024"})," \u2014 Reasoning models \u2014 OpenAI's o1, DeepSeek-R1, and subsequently Claude's extended thinking mode demonstrate that training models to produce explicit reasoning chains (chain-of-thought) before answering dramatically improves performance on mathematical and logical tasks."]}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.strong,{children:"2024"})," \u2014 Long context \u2014 Context windows extend from 4K (GPT-3) to 8K (GPT-4) to 128K (GPT-4 Turbo), 200K (Claude 3), and 1M+ tokens (Gemini 1.5 Pro). Entire codebases or books fit in a single context."]}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.strong,{children:"2025"})," \u2014 Agents enter production \u2014 Tool use, multi-step planning, and computer use capabilities mature. Agent frameworks (LangGraph, CrewAI, Claude's computer use) move from demos to production deployments at scale."]})]})}function c(e={}){let{wrapper:n}={...(0,i.R)(),...e.components};return n?(0,r.jsx)(n,{...e,children:(0,r.jsx)(h,{...e})}):h(e)}},8453(e,n,s){s.d(n,{R:()=>a,x:()=>o});var t=s(6540);let r={},i=t.createContext(r);function a(e){let n=t.useContext(i);return t.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function o(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(r):e.components||r:a(e.components),t.createElement(i.Provider,{value:n},e.children)}}}]);